from fastapi import FastAPI, HTTPException

app = FastAPI()

FLEET = {101: "{{line_a}}", 204: "{{line_b}}", 350: "{{line_a}}", 412: "{{line_a}}", 520: "{{line_b}}"}


def one(vehicle_id: int) -> dict[str, object]:
    if vehicle_id not in FLEET:
        raise HTTPException(status_code=404, detail="Not in the fleet")
    return {"route": "one", "id": vehicle_id, "line": FLEET[vehicle_id]}


def special() -> dict[str, object]:
    return {"route": "{{special}}", "id": 350}


def search(line: str | None, limit: int) -> dict[str, object]:
    ids = [i for i, ln in FLEET.items() if line is None or ln == line][:limit]
    return {"route": "search", "count": len(ids), "ids": ids}


